def newList(nums, m, newnums):
	for num in nums:
		x = num
		while x % m == 0:
			x //= m
		if not newnums or newnums[-1][0] != x:
			newnums.append([x, num // x])
		else:
			newnums[-1][1] += num // x
	return newnums
